_ACCOUNT_IDENTITY_CACHE_FILE = Path(tempfile.gettempdir()) / "Follow.ImpalaJump.accounts.json"
_ACCOUNT_IDENTITY_CACHE_LOCK = threading.Lock()

_APP_LIFECYCLE_LOCK = threading.Lock()
_APP_DASHBOARD_SEEN = False
_APP_LAST_HEARTBEAT = 0.0
_APP_CLOSE_REQUESTED_AT = None
APP_CLOSE_GRACE_SECONDS = 5.0
APP_HEARTBEAT_TIMEOUT_SECONDS = 120.0


def _dashboard_heartbeat():
    global _APP_DASHBOARD_SEEN, _APP_LAST_HEARTBEAT, _APP_CLOSE_REQUESTED_AT
    with _APP_LIFECYCLE_LOCK:
        _APP_DASHBOARD_SEEN = True
        _APP_LAST_HEARTBEAT = time.monotonic()
        _APP_CLOSE_REQUESTED_AT = None


def _dashboard_close_requested():
    global _APP_CLOSE_REQUESTED_AT
    with _APP_LIFECYCLE_LOCK:
        _APP_CLOSE_REQUESTED_AT = time.monotonic()


def _dashboard_watchdog(server):
    while True:
        time.sleep(1.0)
        now = time.monotonic()
        should_stop = False
        with _APP_LIFECYCLE_LOCK:
            if _APP_CLOSE_REQUESTED_AT is not None:
                should_stop = (now - _APP_CLOSE_REQUESTED_AT) >= APP_CLOSE_GRACE_SECONDS
            elif _APP_DASHBOARD_SEEN and _APP_LAST_HEARTBEAT:
                should_stop = (now - _APP_LAST_HEARTBEAT) >= APP_HEARTBEAT_TIMEOUT_SECONDS
        if should_stop:
            try:
                server.shutdown()
            except Exception:
                pass
            return


def _open_existing_instance_if_running():
    # A second EXE opens the already running dashboard instead of creating
    # another Selenium/Chrome session.
    global _SINGLE_INSTANCE_HANDLE
    if os.name != "nt":
        return False
    try:
        import ctypes
        from ctypes import wintypes
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, wintypes.BOOL, wintypes.LPCWSTR]
        kernel32.CreateMutexW.restype = wintypes.HANDLE
        handle = kernel32.CreateMutexW(None, False, r"Local\Follow.ImpalaJump.SingleInstance")
        if not handle:
            return False
        already_running = ctypes.get_last_error() == 183
        _SINGLE_INSTANCE_HANDLE = handle
        if not already_running:
            try:
                _INSTANCE_STATE_FILE.unlink(missing_ok=True)
            except Exception:
                pass
            return False
        for _ in range(20):
            try:
                data = json.loads(_INSTANCE_STATE_FILE.read_text(encoding="utf-8"))
                url = str(data.get("url") or "").strip()
                if url.startswith("http://127.0.0.1:"):
                    webbrowser.open(url, new=2)
                    return True
            except Exception:
                pass
            time.sleep(0.15)
        try:
            ctypes.windll.user32.MessageBoxW(None, "Follow.ImpalaJump is already running.", "Follow.ImpalaJump", 0x40)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _write_instance_state(url):
    if os.name != "nt":
        return
    try:
        _INSTANCE_STATE_FILE.write_text(
            json.dumps({"url": url, "pid": os.getpid(), "version": APP_VERSION}),
            encoding="utf-8",
        )
    except Exception:
        pass


def _clear_instance_state():
    if os.name != "nt":
        return
    try:
        _INSTANCE_STATE_FILE.unlink(missing_ok=True)
    except Exception:
        pass


class FollowError(Exception):
    def __init__(self, code, message, status=500):
        super().__init__(message)
        self.code = code
        self.message = message
        self.status = status


def normalize_username(value):
    value = str(value or "").strip()
    value = re.sub(r"^@+", "", value)
    value = re.sub(r"^https?://(www\.)?instagram\.com/", "", value, flags=re.I)
    value = value.split("?")[0].split("#")[0].split("/")[0].strip()
    return value


def valid_username(username):
    return bool(username and len(username) <= 30 and re.fullmatch(r"[A-Za-z0-9._]+", username))


def extract_lsd(html):
    patterns = [
        r'"LSD",\[\],\{"token":"([^"]+)"',
        r'\["LSD",\[\],\{"token":"([^"]+)"\}',
        r'"token":"([^"]+)".{0,300}"LSD"',
    ]
    for pattern in patterns:
        match = re.search(pattern, html or "", flags=re.S)
        if match:
            return match.group(1)
    return None


def extract_user_id(html, username):
    u = re.escape(username)
    patterns = [
        rf'"id":"(\d+)".{{0,15000}}"username":"{u}"',
        rf'"username":"{u}".{{0,15000}}"id":"(\d+)"',
        rf'\\"id\\":\\"(\d+)\\".{{0,15000}}\\"username\\":\\"{u}\\"',
        rf'\\"username\\":\\"{u}\\".{{0,15000}}\\"id\\":\\"(\d+)\\"',
        rf'"pk":"(\d+)".{{0,15000}}"username":"{u}"',
        rf'"username":"{u}".{{0,15000}}"pk":"(\d+)"',
    ]
    for pattern in patterns:
        match = re.search(pattern, html or "", flags=re.I | re.S)
        if match:
            return match.group(1)
    return None


def _load_account_identity_cache():
    with _ACCOUNT_IDENTITY_CACHE_LOCK:
        try:
            raw = json.loads(_ACCOUNT_IDENTITY_CACHE_FILE.read_text(encoding="utf-8"))
            return raw if isinstance(raw, dict) else {}
        except Exception:
            return {}


def _get_cached_account_identity(username):
    value = _load_account_identity_cache().get(normalize_username(username)) or {}
    return value if isinstance(value, dict) else {}


def _save_cached_account_identity(username, user_id=None):
    username = normalize_username(username)
    if not username:
        return
    with _ACCOUNT_IDENTITY_CACHE_LOCK:
        try:
            try:
                cache = json.loads(_ACCOUNT_IDENTITY_CACHE_FILE.read_text(encoding="utf-8"))
                if not isinstance(cache, dict):
                    cache = {}
            except Exception:
                cache = {}
            item = cache.get(username) if isinstance(cache.get(username), dict) else {}
            if user_id:
                item["user_id"] = str(user_id)
            item["updated_at"] = int(time.time())
            cache[username] = item
            tmp = _ACCOUNT_IDENTITY_CACHE_FILE.with_suffix(".tmp")
            tmp.write_text(json.dumps(cache, ensure_ascii=False), encoding="utf-8")
            tmp.replace(_ACCOUNT_IDENTITY_CACHE_FILE)
        except Exception:
            pass


class InstagramFollowers:
    def __init__(self):
        self.driver = None
        self.lock = threading.RLock()
        self.bootstrap_cache = {}

    @staticmethod
    def _is_dead_session_error(value):
        text = str(value or "").lower()
        return any(marker in text for marker in (
            "invalid session id", "session deleted", "no such window",
            "target window already closed", "chrome not reachable",
            "not connected to devtools", "disconnected", "web view not found",
            "unable to receive message from renderer",
        ))

    def _driver_is_alive(self):
        if self.driver is None:
            return False
        try:
            _ = self.driver.session_id
            _ = self.driver.current_window_handle
            return True
        except Exception:
            return False

    def _dispose_driver(self):
        driver = self.driver
        self.driver = None
        self.bootstrap_cache.clear()
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                pass

    def start(self, force_new=False):
        if force_new:
            self._dispose_driver()
        elif self.driver is not None:
            if self._driver_is_alive():
                return
            self._dispose_driver()

        options = Options()
        if HEADLESS:
            options.add_argument("--headless=new")
        options.add_argument("--window-size=1100,850")
        options.add_argument("--lang=en-US")
        options.add_argument("--disable-notifications")
        options.add_argument("--disable-popup-blocking")
        options.add_argument("--no-first-run")
        options.add_argument("--no-default-browser-check")
        options.add_argument("--disable-gpu")
        options.add_argument("--disable-backgrounding-occluded-windows")
        options.add_argument("--disable-renderer-backgrounding")
        options.add_argument("--disable-background-timer-throttling")

        last_exc = None
        for attempt in range(1, 4):
            driver = None
            try:
                driver = webdriver.Chrome(options=options)
                driver.set_page_load_timeout(30)
                driver.set_script_timeout(30)
                _ = driver.current_window_handle
                self.driver = driver
                return
            except Exception as exc:
                last_exc = exc
                if driver is not None:
                    try:
                        driver.quit()
                    except Exception:
                        pass
                self.driver = None
                if attempt < 3:
                    time.sleep(0.8)

        raise FollowError(
            "CHROME_START_FAILED",
            "Could not start the automated browser. Check the internet connection and try again.",
            500,
        ) from last_exc

    def close(self):
        with self.lock:
            self._dispose_driver()

    def _safe_get(self, url, label="Instagram page", attempts=3):
        for attempt in range(1, attempts + 1):
            self.start(force_new=(attempt > 1))
            try:
                self.driver.get(url)
                _ = self.driver.current_window_handle
                return
            except Exception as exc:
                dead = self._is_dead_session_error(exc) or not self._driver_is_alive()
                if not dead:
                    raise FollowError("BROWSER_NAVIGATION_FAILED", f"Could not open {label}. Please try again.", 502)
                self._dispose_driver()
                if attempt < attempts:
                    time.sleep(0.8)

        raise FollowError(
            "BROWSER_SESSION_RECOVERY_FAILED",
            "The automated browser closed unexpectedly and could not be restored. Please try again.",
            502,
        )

    def run_with_browser_recovery(self, operation, attempts=3):
        for attempt in range(1, attempts + 1):
            try:
                with self.lock:
                    self.start(force_new=(attempt > 1))
                    return operation()
            except FollowError as exc:
                dead = exc.code == "BROWSER_SESSION_RECOVERY_FAILED" or self._is_dead_session_error(exc.message)
                if not dead:
                    raise
            except Exception as exc:
                dead = self._is_dead_session_error(exc) or not self._driver_is_alive()
                if not dead:
                    raise
            with self.lock:
                self._dispose_driver()
            if attempt < attempts:
                time.sleep(0.8)

        raise FollowError(
            "BROWSER_SESSION_RECOVERY_FAILED",
            "The automated browser closed unexpectedly and could not be restored. Please try again.",
            502,
        )

    def get_lsd_from_page(self):
        script = r'''
        try {
            if (window.require) {
                const value = window.require('LSD');
                if (value && value.token) return value.token;
            }
        } catch (e) {}
        return null;
        '''
        try:
            return self.driver.execute_script(script)
        except Exception:
            return None

    def bootstrap(self, username, force=False):
        with self.lock:
            self.start()
            now = time.time()
            cached = self.bootstrap_cache.get(username)
            if not force and cached and now - cached["created_at"] < BOOTSTRAP_TTL_SECONDS:
                try:
                    if "instagram.com" in (self.driver.current_url or ""):
                        return cached
                except Exception:
                    pass

            profile_url = f"{INSTAGRAM_BASE}/{username}/"
            identity = _get_cached_account_identity(username)
            cached_user_id = str(identity.get("user_id") or "").strip() or None
            html = ""
            current_url = ""
            lsd = None
            user_id = None
            login_wall_seen = False

            for profile_attempt in range(1, 5):
                if profile_attempt > 1:
                    self._dispose_driver()
                    time.sleep(min(6.0, 1.5 * profile_attempt))

                self._safe_get(profile_url, "Instagram profile", attempts=2)
                deadline = time.time() + 14
                html = ""
                current_url = ""

                while time.time() < deadline:
                    try:
                        ready = self.driver.execute_script("return document.readyState")
                        html = self.driver.execute_script("return document.documentElement.outerHTML") or ""
                        current_url = self.driver.current_url or ""
                    except Exception:
                        ready, html, current_url = "", "", ""

                    possible_user_id = extract_user_id(html, username)
                    on_login_url = "/accounts/login" in current_url.lower()
                    if possible_user_id or on_login_url:
                        break
                    time.sleep(0.35 if ready in ("interactive", "complete") and len(html) > 180000 else 0.5)

                time.sleep(0.8)
                try:
                    html = self.driver.execute_script("return document.documentElement.outerHTML") or html
                    current_url = self.driver.current_url or current_url
                except Exception:
                    pass

                lsd = self.get_lsd_from_page() or extract_lsd(html)
                extracted_user_id = extract_user_id(html, username)
                user_id = extracted_user_id or cached_user_id

                on_login_url = "/accounts/login" in current_url.lower()
                has_login_form = bool(re.search(
                    r'<input[^>]+(?:name=["\']password["\']|type=["\']password["\'])',
                    html,
                    flags=re.I,
                ))
                login_wall = bool(on_login_url or (has_login_form and not extracted_user_id))

                if lsd and user_id:
                    if login_wall:
                        login_wall_seen = True
                    break
                if login_wall:
                    login_wall_seen = True
                    continue

            if not lsd or not user_id:
                if login_wall_seen:
                    raise FollowError(
                        "INSTAGRAM_LOGIN_WALL",
                        "Instagram temporarily requested login from the anonymous browser. Follow.ImpalaJump will retry automatically.",
                        502,
                    )
                if not lsd:
                    raise FollowError("LSD_NOT_FOUND", "Could not prepare the anonymous Instagram session yet.", 502)
                raise FollowError("USER_ID_NOT_FOUND", "Could not resolve the public Instagram account yet.", 502)

            result = {
                "lsd": lsd,
                "user_id": user_id,
                "profile_url": profile_url,
                "created_at": now,
            }
            self.bootstrap_cache[username] = result
            _save_cached_account_identity(username, user_id=user_id)
            return result

    def graphql(self, username, bootstrap):
        with self.lock:
            variables = {
                "enable_integrity_filters": True,
                "id": bootstrap["user_id"],
                "__relay_internal__pv__PolarisCannesGuardianExperienceEnabledrelayprovider": True,
                "__relay_internal__pv__PolarisCASB976ProfileEnabledrelayprovider": False,
                "__relay_internal__pv__PolarisWebSchoolsEnabledrelayprovider": False,
                "__relay_internal__pv__PolarisRepostsConsumptionEnabledrelayprovider": True,
                "__relay_internal__pv__PolarisShortDramaEnabledrelayprovider": False,
                "__relay_internal__pv__PolarisLongformEnabledrelayprovider": False,
            }
            payload = {
                "variables": variables,
                "docId": PROFILE_DOC_ID,
                "lsd": bootstrap["lsd"],
                "appId": IG_APP_ID,
                "asbdId": IG_ASBD_ID,
            }

            js = r'''
            const input = arguments[0];
            const done = arguments[arguments.length - 1];
            (async () => {
                try {
                    const body = new URLSearchParams({
                        fb_api_caller_class: 'RelayModern',
                        fb_api_req_friendly_name: 'PolarisProfilePageContentQuery',
                        server_timestamps: 'true',
                        variables: JSON.stringify(input.variables),
                        doc_id: input.docId,
                        lsd: input.lsd
                    });
                    const response = await fetch('/api/graphql', {
                        method: 'POST',
                        credentials: 'omit',
                        cache: 'no-store',
                        headers: {
                            'Content-Type': 'application/x-www-form-urlencoded',
                            'X-IG-App-ID': input.appId,
                            'X-ASBD-ID': input.asbdId,
                            'X-FB-Friendly-Name': 'PolarisProfilePageContentQuery',
                            'X-FB-LSD': input.lsd
                        },
                        body
                    });
                    done({status: response.status, text: await response.text()});
                } catch (e) {
                    done({status: 0, error: String(e && e.message ? e.message : e), text: ''});
                }
            })();
            '''

            try:
                response = self.driver.execute_async_script(js, payload)
            except Exception as exc:
                raise FollowError("GRAPHQL_BROWSER_ERROR", "Chrome could not execute the Instagram request.", 502) from exc

            status = int((response or {}).get("status") or 0)
            text = (response or {}).get("text") or ""

            if status == 429:
                raise FollowError("INSTAGRAM_RATE_LIMIT", "Instagram temporarily rate-limited public requests.", 429)
            if status in (401, 403):
                raise FollowError("INSTAGRAM_LOGIN_WALL", "Instagram temporarily rejected the anonymous public request.", 502)
            if status != 200:
                raise FollowError("GRAPHQL_REQUEST_FAILED", f"Instagram returned HTTP {status}.", 502)

            try:
                data = json.loads(text)
            except Exception:
                raise FollowError("INVALID_GRAPHQL_RESPONSE", "Instagram returned an invalid response.", 502)

            user = (data.get("data") or {}).get("user")
            if not user:
                raise FollowError("PROFILE_DATA_NOT_FOUND", "Instagram returned no public profile data.", 502)

            try:
                followers = int(user.get("follower_count"))
            except (TypeError, ValueError):
                raise FollowError("FOLLOWER_COUNT_INVALID", "Instagram returned an invalid follower count.", 502)

            result = {
                "success": True,
                "username": user.get("username") or username,
                "userId": bootstrap["user_id"],
                "name": user.get("full_name") or "",
                "followers": followers,
                "private": bool(user.get("is_private")),
                "verified": bool(user.get("is_verified")),
                "updatedAt": time.strftime("%Y-%m-%dT%H:%M:%S%z", time.localtime()),
            }
            _save_cached_account_identity(result["username"], user_id=bootstrap["user_id"])
            return result

    def get_profile(self, username):
        bootstrap = self.bootstrap(username)
        try:
            return self.graphql(username, bootstrap)
        except FollowError as exc:
            if exc.code in {
                "GRAPHQL_REQUEST_FAILED",
                "INVALID_GRAPHQL_RESPONSE",
                "PROFILE_DATA_NOT_FOUND",
                "INSTAGRAM_LOGIN_WALL",
            }:
                bootstrap = self.bootstrap(username, force=True)
                return self.graphql(username, bootstrap)
            raise


