class Handler(BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        pass

    def send_bytes(self, data, content_type="application/octet-stream", status=200):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)

    def send_json(self, data, status=200):
        self.send_bytes(
            json.dumps(data, ensure_ascii=False).encode("utf-8"),
            "application/json; charset=utf-8",
            status,
        )

    def do_POST(self):
        parsed = urlparse(self.path)
        if parsed.path == "/api/closing":
            _dashboard_close_requested()
            self.send_json({"success": True})
            return
        self.send_json({"success": False, "error": "NOT_FOUND"}, 404)

    def do_GET(self):
        parsed = urlparse(self.path)
        if parsed.path == "/":
            _dashboard_heartbeat()
            self.send_bytes(HTML.encode("utf-8"), "text/html; charset=utf-8")
            return

        if parsed.path == "/favicon.ico":
            try:
                self.send_bytes(base64.b64decode(FAVICON_B64), "image/x-icon")
            except Exception:
                self.send_bytes(b"", "image/x-icon", 404)
            return

        if parsed.path == "/api/heartbeat":
            _dashboard_heartbeat()
            self.send_json({"success": True})
            return

        if parsed.path == "/api/version":
            self.send_json({"success": True, "version": APP_VERSION})
            return

        if parsed.path == "/api/followers":
            query = parse_qs(parsed.query)
            username = normalize_username((query.get("username") or [""])[0])
            if not valid_username(username):
                self.send_json(
                    {"success": False, "error": "INVALID_USERNAME", "message": "Invalid Instagram username."},
                    400,
                )
                return
            try:
                data = followers_instagram.run_with_browser_recovery(
                    lambda: followers_instagram.get_profile(username)
                )
                self.send_json(data)
            except FollowError as exc:
                self.send_json(
                    {"success": False, "error": exc.code, "message": exc.message},
                    exc.status,
                )
            except Exception as exc:
                self.send_json(
                    {"success": False, "error": "INTERNAL_ERROR", "message": str(exc)},
                    500,
                )
            return

        self.send_json({"success": False, "error": "NOT_FOUND"}, 404)


def main():
    if _open_existing_instance_if_running():
        return

    server = ThreadingHTTPServer((HOST, PORT), Handler)
    actual_port = int(server.server_address[1])
    dashboard_url = f"http://{HOST}:{actual_port}/?v={APP_VERSION}"
    _write_instance_state(dashboard_url)

    threading.Thread(
        target=_dashboard_watchdog,
        args=(server,),
        daemon=True,
        name="Follow.ImpalaJump-dashboard-watchdog",
    ).start()

    def open_dashboard():
        try:
            webbrowser.open(dashboard_url, new=2)
        except Exception:
            pass

    threading.Timer(0.8, open_dashboard).start()

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
        followers_instagram.close()
        _clear_instance_state()


if __name__ == "__main__":
    main()
